def projection(raw):
    pos=0;items=0;values=[];rebuilt=bytearray();counts={}
    def scalar(t,emit=True):
        nonlocal pos
        fmt={'i':'<i','u':'<I','b':'<B'}[t];n=struct.calcsize(fmt)
        v=struct.unpack_from(fmt,raw,pos)[0];pos+=n
        rebuilt.extend(struct.pack(fmt,v))
